    typedef CGAL::Exact_predicates_exact_constructions_kernel Kernel;
    typedef CGAL::Polygon_2<Kernel> Polygon2_CGAL;
    typedef CGAL::Polygon_with_holes_2<Kernel> PolygonWithHoles2_CGAL;
    typedef CGAL::General_polygon_set_2<Kernel> GeneralPolygonSet2;

    GeneralPolygonSet2 gps1, gps2;

    Polygon2_CGAL poly1_cgal;
    for (const auto& p : P1.vectorPoints()) {
        poly1_cgal.push_back(Kernel::Point_2(p.x, p.y));
    }
    gps1.insert(poly1_cgal);

    Polygon2_CGAL poly2_cgal;
    for (const auto& p : P2.vectorPoints()) {
        poly2_cgal.push_back(Kernel::Point_2(p.x, p.y));
    }
    gps2.insert(poly2_cgal);

    GeneralPolygonSet2 result_gps = gps1.join(gps2);

    std::vector<PolygonWithHoles2d> result;
    for (auto it = result_gps.begin(); it != result_gps.end(); ++it) {
        PolygonWithHoles2d pwh;

        const Polygon2_CGAL& outer = it->outer_boundary();
        for (auto v = outer.vertices_begin(); v != outer.vertices_end(); ++v) {
            pwh.outer.pushBack(cg3::Point2d(CGAL::to_double(v->x()), CGAL::to_double(v->y())));
        }

        for (auto hole_it = it->holes_begin(); hole_it != it->holes_end(); ++hole_it) {
            cg3::Polygon2 hole;
            for (auto v = hole_it->vertices_begin(); v != hole_it->vertices_end(); ++v) {
                hole.pushBack(cg3::Point2d(CGAL::to_double(v->x()), CGAL::to_double(v->y())));
            }
            pwh.holes.push_back(hole);
        }
        result.push_back(pwh);
    }

    return result;
