            pwh.outer.pushBack(cg3::Point2d(CGAL::to_double(v->x()), CGAL::to_double(v->y())));
        }

        for (auto hole_it = it->holes_begin(); hole_it != it->holes_end(); ++hole_it) {
            cg3::Polygon2 hole;
            for (auto v = hole_it->vertices_begin(); v != hole_it->vertices_end(); ++v) {
                hole.pushBack(cg3::Point2d(CGAL::to_double(v->x()), CGAL::to_double(v->y())));
            }
            pwh.holes.push_back(hole);
        }
        result.push_back(pwh);
    }

    return result;

